for (let i = 0; i < 6; i++) {
  takoyakiLevelBuilder.addTileToBank(
    `takoyaki-end-${i}`,
    3e3,
    {
      renderer: "takoyaki-tile",
      props: { start: i, hasCircle: true }
    },
    "takoyaki-end"
  );
  for (let j = i + 1; j < 6; j++) {
    takoyakiLevelBuilder.addTileToBank(
      `takoyaki-circle-${i}-${j}`,
      3e3,
      {
        renderer: "takoyaki-tile",
        props: { start: i, end: j, hasCircle: true }
      },
      "takoyaki-circle"
    );
    takoyakiLevelBuilder.addTileToBank(
      `takoyaki-no-circle-${i}-${j}`,
      3e3,
      {
        renderer: "takoyaki-tile",
        props: { start: i, end: j, hasCircle: false }
      },
      "takoyaki-no-circle"
    );
  }
}
